float voronoi(vec2 uv) { 
    vec2 id = floor(uv); 
    vec2 f = fract(uv); 
    vec2 nearestStarPos = vec2(0.0);

    float minDist = 1.0;
    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            vec2 neighbor = vec2(i, j);
            vec2 randomOffset = vec2(noise(id + neighbor), noise(id + neighbor + vec2(0.5, 0.5)));
            vec2 diff = neighbor + vec2(randomOffset) - f;
            float dist = length(diff);
            minDist = min(minDist, dist);

            if(dist<minDist)
            {
            minDist=dist;
            nearestStarPos = neighbor + randomOffset;
            }
        }       
    }

    float Connect=length(uv-nearestStarPos);

    if(Connect<.1){
        return 1.;
    }


    return minDist;
}

float random (in vec2 st) {
    return fract(sin(dot(st.xy,
                         vec2(12.9898,78.233)))*
        43758.5453123);
}
float noise0 (in vec2 st) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);

    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

#define OCTAVES 6
float fbm (in vec2 st) {
    float value = 0.0;
    float amplitude = .5;
    float frequency = 0.;

    for (int i = 0; i < OCTAVES; i++) {
        value += amplitude * noise0(st);
        st *= 2.968;
        amplitude *= 0.388;
    }
    return value;
}


vec3 Bloom(in vec2 texcoord,vec3 color,vec2 texs) {
    float intensity = 1.5;
    int radius = 5;
    float threshold = 0.4;
    float count = 0.0;

    for (int i = -radius; i <= radius; ++i) {
        for (int j = -radius; j <= radius; ++j) {
            vec2 offset = vec2(i, j) * intensity / texs;
            color += texture(iChannel0, texcoord + offset).rgb;
            count += 1.0;
        }
    }

    color /= count;

    return color;
}
float sdEquilateralTriangle( in vec2 p, in float r )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}
float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

vec3 drawTree(vec2 uv, vec2 pos) {
    vec3 color = vec3(0.0);

    color += smoothstep(0.01, 0.01-0.01, sdEquilateralTriangle(uv - (pos + vec2(0.0, 0.15)), 0.1));
    color += smoothstep(0.01, 0.01-0.01, sdEquilateralTriangle(uv - (pos + vec2(0.0, 0.0)), 0.1));
    color += smoothstep(0.01, 0.01-0.01, sdEquilateralTriangle(uv - (pos + vec2(0.0, -0.14)), 0.1));
    color += smoothstep(0.01, 0.01-0.01, sdBox(uv - (pos + vec2(0.0, -0.25)), vec2(0.01, .1)));

    return color;
}

float smin( float a, float b, float k )
{
    k *= 2.0;
    float x = b-a;
    return 0.5*( a+b-sqrt(x*x+k*k) );
}

